from collections import deque

class Dinic:
    def __init__(self,n):
        self.n=n
        self.adj=[[] for _ in range(n)]
    def add_edge(self,u,v,cap):
        self.adj[u].append([v,cap,len(self.adj[v])])
        self.adj[v].append([u,0,len(self.adj[u])-1])
    def bfs(self,s,t,level):
        for i in range(self.n):
            level[i]=-1
        level[s]=0
        q=deque([s])
        while q:
            u=q.popleft()
            for i,(v,cap,rev) in enumerate(self.adj[u]):  
                if level[v]<0:
                    level[v]=level[u]+1
                    q.append(v)
        return level[t]>=0
    def send_flow(self,u,t,flow,level,it):
        if u==t:
            return flow
        while it[u]<len(self.adj[u]):
            v,cap,rev = self.adj[u][it[u]]
            if cap>0 and level[v]==level[u]+1:
                curr_flow=min(flow,cap)
                temp=self.send_flow(v,t,curr_flow,level,it)
                if temp>0:
                    self.adj[u][it[u]][1]-=temp
                    self.adj[v][rev][1]+=temp
                    return temp
            it[u]+=1
        return 0
    def max_flow(self,s,t):
        flow=0
        level=[-1]*self.n
        while self.bfs(s,t,level):
            it=[0]*self.n
            pushed=self.send_flow(s,t,float('inf'),level,it)
            while pushed>0:
                flow+=pushed
                pushed=self.send_flow(s,t,float('inf'),level,it)
        return flow
