using System;
using System.Drawing;
using System.Windows.Forms;

namespace Solution
{
    public partial class MainForm : Form
    {
        private float birdY;
        private float birdVelocity;
        private const float gravity = 0.5f;
        private const float jumpForce = -10f;
        private int pipeWidth = 60;
        private int pipeGap = 150;
        private int pipeX;
        private Random random;
        private bool gameOver;

        public MainForm()
        {
            Width = 800;
            Height = 600;
            DoubleBuffered = true;
            var timer = new System.Windows.Forms.Timer();
            timer.Interval = 16;
            timer.Tick += (s, e) => GameLoop();
            timer.Start();

            birdY = ClientSize.Height / 2;
            birdVelocity = 0;
            pipeX = ClientSize.Width;
            random = new Random();
            gameOver = false;

            this.KeyDown += (s, e) =>
            {
                if (e.KeyCode == Keys.Space && !gameOver)
                {
                    birdVelocity = jumpForce;
                }
                else if (gameOver)
                {
                    ResetGame();
                }
            };
        }

        private void GameLoop()
        {
            if (!gameOver)
            {
                // Обновление позиции птички
                birdVelocity += gravity;
                birdY += birdVelocity;

                // Обновление позиции труб
                pipeX -= 5;

                // Проверка на столкновение с трубами
                if (pipeX < 0)
                {
                    pipeX = ClientSize.Width;
                    pipeGap = random.Next(100, 300);
                }

                // Проверка на выход за границы
                if (birdY > ClientSize.Height || birdY < 0)
                {
                    gameOver = true;
                }

                // Проверка на столкновение с трубами
                if (pipeX < ClientSize.Width / 2 + 20 && pipeX + pipeWidth > ClientSize.Width / 2 - 20)
                {
                    if (birdY < pipeGap || birdY > pipeGap + 100)
                    {
                        gameOver = true;
                    }
                }

                Invalidate();
            }
        }

        private void ResetGame()
        {
            birdY = ClientSize.Height / 2;
            birdVelocity = 0;
            pipeX = ClientSize.Width;
            gameOver = false;
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            Graphics g = e.Graphics;
            g.Clear(Color.Black);

            // Рисуем птичку
            g.FillEllipse(Brushes.Yellow, ClientSize.Width / 2 - 20, birdY - 20, 40, 40);

            // Рисуем трубы
            g.FillRectangle(Brushes.Green, pipeX, 0, pipeWidth, pipeGap);
            g.FillRectangle(Brushes.Green, pipeX, pipeGap + 100, pipeWidth, ClientSize.Height - pipeGap - 100);

            // Если игра окончена, выводим сообщение
            if (gameOver)
            {
                g.DrawString("Game Over! Press Space to Restart", new Font("Arial", 16), Brushes.White, new PointF(50, ClientSize.Height / 2));
            }
        }

        [STAThread]
        static void Main()
        {
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            Application.Run(new MainForm());
        }
    }
}

