using Timer = System.Windows.Forms.Timer;

public class PongGame : Form
{
    private Timer timer;
    private Rectangle player1, player2, ball;
    private int ballSpeedX = 5, ballSpeedY = 5;
    private const int paddleWidth = 10, paddleHeight = 60, ballSize = 10;

    public PongGame()
    {
        this.DoubleBuffered = true;
        this.Width = 800;
        this.Height = 400;
        this.Text = "Pong Game";

        player1 = new Rectangle(30, (this.ClientSize.Height - paddleHeight) / 2, paddleWidth, paddleHeight);
        player2 = new Rectangle(this.ClientSize.Width - 40, (this.ClientSize.Height - paddleHeight) / 2, paddleWidth, paddleHeight);
        ball = new Rectangle(this.ClientSize.Width / 2 - ballSize / 2, this.ClientSize.Height / 2 - ballSize / 2, ballSize, ballSize);

        timer = new Timer();
        timer.Interval = 20; // 50 FPS
        timer.Tick += Update;
        timer.Start();

        this.KeyDown += new KeyEventHandler(OnKeyDown);
    }

    private void Update(object sender, EventArgs e)
    {
        ball.X += ballSpeedX;
        ball.Y += ballSpeedY;

        if (ball.Y <= 0 || ball.Y >= this.ClientSize.Height - ballSize)
        {
            ballSpeedY = -ballSpeedY;
        }

        if (ball.IntersectsWith(player1) || ball.IntersectsWith(player2))
        {
            ballSpeedX = -ballSpeedX;
        }

        if (ball.X < 0 || ball.X > this.ClientSize.Width)
        {
            ball.X = this.ClientSize.Width / 2 - ballSize / 2;
            ball.Y = this.ClientSize.Height / 2 - ballSize / 2;
            ballSpeedX = -ballSpeedX;
        }

        Invalidate();
    }

    protected override void OnPaint(PaintEventArgs e)
    {
        base.OnPaint(e);
        e.Graphics.FillRectangle(Brushes.Blue, player1);
        e.Graphics.FillRectangle(Brushes.Red, player2);
        e.Graphics.FillRectangle(Brushes.Black, ball);
    }

    private void OnKeyDown(object sender, KeyEventArgs e)
    {
        if (e.KeyCode == Keys.W && player1.Y > 0)
        {
            player1.Y -= 10;
        }
        if (e.KeyCode == Keys.S && player1.Y < this.ClientSize.Height - paddleHeight)
        {
            player1.Y += 10;
        }
        if (e.KeyCode == Keys.Up && player2.Y > 0)
        {
            player2.Y -= 10;
        }
        if (e.KeyCode == Keys.Down && player2.Y < this.ClientSize.Height - paddleHeight)
        {
            player2.Y += 10;
        }
    }

    [STAThread]
    public static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new PongGame());
    }
}

