using System.Numerics;
using Timer = System.Windows.Forms.Timer;

public class BezierMovement : Form
{
    private Timer timer;
    private int accumulatedTime = 0;
    private const int pointSize = 20;
    private const int fps = 16;
    private const int executionTime = 2000;
    private readonly Vector2[] bezierPoints =
            {
                new Vector2(100, 50),
                new Vector2(120, 150),
                new Vector2(700, 100)
            };
    public BezierMovement()
    {
        DoubleBuffered = true;
        Width = 800;
        Height = 400;

        timer = new Timer();
        timer.Interval = fps;
        timer.Tick += new EventHandler(Loop);
        timer.Start();
    }
    private void Loop(object? sender, EventArgs e)
    {
        //t += 0.01f;
        accumulatedTime += fps;
        if(accumulatedTime > executionTime)
            accumulatedTime = executionTime;

        Invalidate();
    }
    protected override void OnPaint(PaintEventArgs e)
    {
        Graphics g = e.Graphics;
        g.Clear(Color.CornflowerBlue);

        var point = getPositionOnBezier(bezierPoints, (float)accumulatedTime / executionTime);

        g.FillEllipse(Brushes.Yellow, point.X - pointSize / 2, point.Y - pointSize / 2, pointSize, pointSize);
    }

    Vector2 getPositionOnBezier(Vector2[] bezierPoints, float t)
    {
        return t * t * (bezierPoints[0] - 2 * bezierPoints[1] + bezierPoints[2]) + t * (-2 * bezierPoints[0] + 2 * bezierPoints[1]) + bezierPoints[0];
    }

    [STAThread]
    public static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new BezierMovement());
    }
}
